insert into public.permits (slug,destination_id,state_id,permit_name,description,required,mandatory,applicable_to,source,source_url,source_type,last_verified,status,reconfirm_note) values ('ilp-arunachal',null,'AR','Inner Line Permit (ILP)','Indian citizens from outside Arunachal Pradesh need an ILP to enter the state. Apply online (eILP) before travel and carry a printed or digital copy with photo ID.',true,true,'Indian citizens (non-residents of the state)','Government of Arunachal Pradesh — eILP portal','https://eilp.arunachal.gov.in/','official','2026-10-14','verified','Check validity period and fee on the portal when applying.') on conflict (slug) do update set destination_id=excluded.destination_id, state_id=excluded.state_id, permit_name=excluded.permit_name, description=excluded.description, required=excluded.required, mandatory=excluded.mandatory, applicable_to=excluded.applicable_to, source=excluded.source, source_url=excluded.source_url, source_type=excluded.source_type, last_verified=excluded.last_verified, status=excluded.status, reconfirm_note=excluded.reconfirm_note;
